"""Build lecture notes and fixed practice sets from the reviewed 27–28 October recordings.
Dependencies: latex2mathml, matplotlib, numpy. Run from any directory.
No source recordings or participant data are published.
"""
from pathlib import Path
import json, html, re
from latex2mathml.converter import convert
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'assets/math-20261028'
OUT.mkdir(parents=True,exist_ok=True)
LANG=('ru','pl','en')
def tr(tag,ru,pl,en,cls=''):
 attrs=' '.join(f'data-i18n-{l}="{html.escape(t,quote=True)}"' for l,t in zip(LANG,(ru,pl,en)))
 return f'<{tag} {attrs}'+(f' class="{cls}"' if cls else '')+'>'+html.escape(ru)+f'</{tag}>'
def p(ru,pl,en):return tr('p',ru,pl,en)
def m(tex,display=True):
 return convert(tex,display='block' if display else 'inline')
def f(tex):return '<div class="lesson-formula">'+m(tex)+'</div>'
def sec(id,t,*body):return f'<section class="lesson-section" id="{id}">'+tr('h2',*t)+''.join(body)+'</section>'
def example(t,*steps):return '<div class="worked">'+tr('h3',*t)+''.join(steps)+'</div>'
def fig(name,t):return '<figure><img src="assets/math-20261028/'+name+'.svg" alt="'+html.escape(t[0],quote=True)+'" loading="lazy">'+tr('figcaption',*t)+'</figure>'
def warn(ru,pl,en):return '<aside class="lesson-warning">'+p(ru,pl,en)+'</aside>'
PAGES=[]
def page(slug,title,desc,date,source,sections,practice):
 PAGES.append(dict(slug=slug,title=title,desc=desc,date=date,source=source,sections=sections,practice=practice))

