SETS=[]
def addset(id,title,items,lesson):
 assert len(items)==10
 SETS.append(dict(id=id,title=title,items=items,generator=False,blurb='Материал 27–28 октября · 10 дополнительных задач с ответами и объяснениями.',lesson=lesson))
def E(q,a,w):return dict(q=q,a=a,w=w)
def im(t):return m(t,False)
addset('vieta-sums','Формулы Виета: сумма, произведение и знаки',[E('Для '+im(fr'x^2-{k+2}x+{2*k}=0')+' найди сумму, произведение и знаки корней.',im(fr'S={k+2},\ P={2*k};\quad x_1=2,\ x_2={k}'), 'По Виету S=−b/a, P=c/a. Произведение и сумма положительны, значит оба корня положительны.'+(' Здесь корень 2 двойной.' if k==2 else ' Корни различны.')) for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('vieta-expressions','Виет: выражения через корни',[E('Не находя корней '+im(fr'x^2-{k+3}x+{3*k}=0')+', найди '+im(r'x_1^2+x_2^2\quad\text{and}\quad(x_1-x_2)^2')+'.',im(fr'x_1^2+x_2^2={k*k+9},\quad(x_1-x_2)^2={(k-3)**2}'),im(fr'S={k+3},\ P={3*k};\quad S^2-2P={k*k+9},\quad S^2-4P={(k-3)**2}')) for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('quadratic-parameter','Параметр и число корней',[E('При каких c уравнение '+im(fr'x^2-{2*k}x+c=0')+' имеет два различных действительных корня?',im(fr'c<{k*k}'),im(fr'\Delta={4*k*k}-4c>0\Rightarrow c<{k*k}')+' При равенстве дискриминанта нулю корень только один.') for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('biquadratic','Биквадратные уравнения',[E('Реши '+im(fr'x^4+{k+1}x^2-{k*(2*k+1)}=0')+'.',im(fr'x=\pm\sqrt{{{k}}}'),im(fr't=x^2\ge0:\quad (t-{k})(t+{2*k+1})=0')+' Отрицательный корень t отбрасываем, из положительного получаем два значения x.') for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('poly-grouping','Многочлены: группировка и знак',[E('Реши '+im(fr'x^3-{k}x^2+2x-{2*k}\le0')+'.',im(fr'x\le{k}'),im(fr'x^2(x-{k})+2(x-{k})=(x-{k})(x^2+2)')+' Второй множитель всегда положителен, поэтому знак определяется x−'+str(k)+'.') for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('horner-practice','Горнер: извлечение линейного множителя',[E('Известно, что '+im(fr'W(x)=x^3-{k}x^2+x-{k}')+' имеет корень '+str(k)+'. Разложи W и найди все действительные корни.',im(fr'W(x)=(x-{k})(x^2+1),\quad x={k}'), 'Коэффициенты схемы Горнера: '+f'1, −{k}, 1, −{k}'+'. После деления на x−'+str(k)+' получаем 1, 0, 1 и остаток 0. Квадрат x²+1 положителен.') for k in range(1,11)],'polynomials-vieta-2026-10-27')
addset('rational-domain','Рациональные функции: область и сокращение',[E('Найди область определения и нули '+im(fr'f(x)=\frac{{x^2-{k*k}}}{{x-{k}}}')+'.',im(fr'D=\mathbb R\setminus\{{{k}\}},\quad x_0=-{k}'),im(fr'f(x)=x+{k}\quad(x\ne{k})')+' Сокращённый множитель не возвращает исключённую точку. Нуль −'+str(k)+' допустим.') for k in range(1,11)],'rational-functions-2026-10-28')
addset('hyperbola-practice','Гипербола: асимптоты и нули',[E('Для '+im(fr'f(x)={k}+\frac{{2}}{{x+1}}')+' найди асимптоты, область определения и нуль.',im(fr'x=-1,\ y={k};\quad D=\mathbb R\setminus\{{-1\}};\quad x_0=-1-\frac2{{{k}}}'), 'Вертикальная асимптота обнуляет знаменатель, горизонтальная равна постоянной части. Для нуля решаем '+im(fr'{k}(x+1)+2=0')+'.') for k in range(1,11)],'rational-functions-2026-10-28')
addset('fraction-division','Деление рациональных выражений',[E('Упрости с указанием области '+im(fr'\frac{{x^2-{k*k}}}{{x+{k}}}\div\frac{{x-{k}}}{{x+{k+1}}}')+'.',im(fr'x+{k+1},\quad x\notin\{{-{k+1},-{k},{k}\}}'), 'Знаменатели обеих дробей ненулевые, числитель делителя тоже ненулевой. Затем раскладываем разность квадратов и умножаем на обратную дробь.') for k in range(1,11)],'rational-functions-2026-10-28')
addset('rational-signs','Рациональные неравенства: метод интервалов',[E('Реши '+im(fr'\frac{{(x+{k})(x-{k+2})}}{{x-1}}\le0')+'.',im(fr'x\in(-\infty,-{k}]\cup(1,{k+2}]'), 'Критические точки '+f'−{k}, 1, {k+2}'+'. Слева направо знаки: −, +, −, +. Нули числителя включаем, точку 1 исключаем.') for k in range(1,11)],'rational-functions-2026-10-28')
addset('absolute-fractions','Модуль в знаменателе',[E('Реши '+im(fr'\frac{{{k+1}}}{{|x-{k}|}}>1')+'.',im(fr'x\in(-1,{k})\cup({k},{2*k+1})'),im(fr'0<|x-{k}|<{k+1}')+' Ненулевое расстояние до '+str(k)+' должно быть меньше '+str(k+1)+'. Центр исключён, границы строгие.') for k in range(1,11)],'rational-functions-2026-10-28')
addset('logs-basic','Логарифмы: определение',[E('Вычисли '+im(fr'\log_2\frac1{{{2**k}}}')+'.',im(fr'-{k}'),im(fr'\frac1{{{2**k}}}=2^{{-{k}}}')+' Логарифм возвращает показатель степени, а не основание.') for k in range(1,11)],'logarithms-2026-10-28')
addset('logs-rules','Логарифмы: объединение выражений',[E('Вычисли '+im(fr'\log_2({k})+\log_2({2**(k+1)})-\log_2({2*k})')+'.',str(k),im(fr'\log_2\left(\frac{{{k}\cdot{2**(k+1)}}}{{{2*k}}}\right)=\log_2({2**k})={k}')+' Все аргументы положительны.') for k in range(1,11)],'logarithms-2026-10-28')
addset('logs-base','Логарифмы: смена основания',[E('Запиши '+im(fr'\log_{{{2**k}}}({3**k})')+' как логарифм с основанием 2.',im(r'\log_2 3'),im(fr'\frac{{\log_2(3^{{{k}}})}}{{\log_2(2^{{{k}}})}}=\frac{{{k}\log_2 3}}{{{k}}}=\log_2 3')) for k in range(1,11)],'logarithms-2026-10-28')
addset('logs-equations','Логарифмические уравнения: переменное основание',[E('Реши '+im(fr'\log_{{x+{k}}}({(k+2)**2})=2')+'.','x=2',im(fr'x+{k}>0,\ x+{k}\ne1;\quad(x+{k})^2=({k+2})^2')+' Положительное основание даёт x+'+str(k)+'='+str(k+2)+', то есть x=2. Отрицательная ветвь запрещена.') for k in range(1,11)],'logarithms-2026-10-28')
addset('exp-equations','Показательные уравнения: общее основание',[E('Реши '+im(fr'4^{{x+1}}=2^{{x+{k+2}}}')+'.',im(fr'x={k}'),im(fr'2^{{2x+2}}=2^{{x+{k+2}}}\Rightarrow2x+2=x+{k+2}\Rightarrow x={k}')) for k in range(1,11)],'logarithms-2026-10-28')
addset('exp-substitution','Показательные уравнения: замена переменной',[E('Реши '+im(fr'9^x+3^x={k*k+k}')+'.',im(fr'x=\log_3 {k}'),im(fr't=3^x>0:\quad t^2+t-{k*k+k}=(t-{k})(t+{k+1})=0')+' Допустим только t='+str(k)+'. Возвращаемся к 3ˣ='+str(k)+'.') for k in range(1,11)],'logarithms-2026-10-28')
