addset('arithmetic-term','Арифметическая прогрессия: член и сумма',[E('Дано '+im(fr'a_1=-{k},\ r=2,\ n={k+3}')+'. Найди '+im(fr'a_{{{k+3}}},\ S_{{{k+3}}}')+'.',im(fr'a_{{{k+3}}}={k+4},\quad S_{{{k+3}}}={2*(k+3)}'),im(fr'a_n=-{k}+2({k+3}-1)={k+4},\quad S_n=\frac{{{k+3}(-{k}+{k+4})}}{{2}}={2*(k+3)}')) for k in range(1,11)],'sequences-2026-10-28')
addset('arithmetic-recover','Арифметическая прогрессия: два члена',[E('Известно '+im(fr'a_2={k+3},\ a_5={k+12}')+'. Найди r, a₁ и общий член.',im(fr'r=3,\quad a_1={k},\quad a_n={k}+3(n-1)'),im(fr'r=\frac{{a_5-a_2}}{{5-2}}=\frac93=3,\quad a_1=a_2-r={k}')) for k in range(1,11)],'sequences-2026-10-28')
addset('geometric-finite','Геометрическая прогрессия: конечная сумма',[E('Дано '+im(fr'a_1={k},\ q=2')+'. Найди a₅ и S₅.',im(fr'a_5={16*k},\quad S_5={31*k}'),im(fr'a_5={k}\cdot2^4={16*k},\quad S_5={k}\frac{{1-2^5}}{{1-2}}={31*k}')+' Для конечной суммы q=2 допустимо; условие |q|<1 здесь не нужно.') for k in range(1,11)],'sequences-2026-10-28')
addset('limits-rational','Пределы: равные степени',[E('Найди '+im(fr'\lim_{{n\to\infty}}\frac{{{k}n^2+3n+1}}{{2n^2+n+4}}')+'.',im(fr'\frac{{{k}}}2'),im(fr'\lim_{{n\to\infty}}\frac{{{k}+3/n+1/n^2}}{{2+1/n+4/n^2}}=\frac{{{k}}}2')+' Делим на n²; дроби с n в знаменателе стремятся к нулю.') for k in range(1,11)],'limits-series-2026-10-28')
addset('limits-degrees','Пределы: разные степени',[E('Найди пределы '+im(fr'\frac{{{k}n^2+1}}{{n^3+2}}\quad\text{{and}}\quad\frac{{{k}n^3+1}}{{2-n^2}}')+' при n→∞.',im(r'0;\quad-\infty'), 'Первое отношение ведёт себя как '+im(fr'\frac{{{k}}}n')+', второе как '+im(fr'-{k}n')+'. Старшие степени определяют рост, коэффициенты — знак.') for k in range(1,11)],'limits-series-2026-10-28')
