addset('series-equations','Уравнения с геометрическим рядом',[E('Реши '+im(fr'1+\frac{{x}}{{{k+1}}}+\left(\frac{{x}}{{{k+1}}}\right)^2+\cdots=2')+'.',im(fr'x=\frac{{{k+1}}}2'),im(fr'\left|\frac{{x}}{{{k+1}}}\right|<1,\quad\frac1{{1-x/{k+1}}}=2\Rightarrow x=\frac{{{k+1}}}2')+' Проверка: q=1/2, поэтому ряд действительно сходится.') for k in range(1,11)],'limits-series-2026-10-28')

